#include "io.h"
#include "vector.h"
#include <stdlib.h>
#include <string.h>

DenseMatrix *dm_read_text(const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;

    int rows, cols;
    if (fscanf(fp, "%d %d", &rows, &cols) != 2) {
        fclose(fp);
        return NULL;
    }

    DenseMatrix *m = dm_create(rows, cols);
    if (!m) { fclose(fp); return NULL; }

    int i, j;
    for (i = 0; i < rows; i++)
        for (j = 0; j < cols; j++)
            if (fscanf(fp, "%lf", &m->data[i * cols + j]) != 1) {
                dm_destroy(m);
                fclose(fp);
                return NULL;
            }

    fclose(fp);
    return m;
}

int dm_write_text(const DenseMatrix *m, const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) return -1;
    dm_print(m, fp);
    fclose(fp);
    return 0;
}

double *vec_read_text(const char *filename, int *n_out)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;

    int n;
    if (fscanf(fp, "%d", &n) != 1 || n <= 0) {
        fclose(fp);
        return NULL;
    }

    double *x = vec_create(n);
    if (!x) { fclose(fp); return NULL; }

    int i;
    for (i = 0; i < n; i++)
        if (fscanf(fp, "%lf", &x[i]) != 1) {
            free(x);
            fclose(fp);
            return NULL;
        }

    fclose(fp);
    *n_out = n;
    return x;
}

int vec_write_text(const double *x, int n, const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) return -1;
    fprintf(fp, "%d\n", n);
    vec_print(x, n, fp);
    fclose(fp);
    return 0;
}
