static COOMatrix *coo_sort_dedup(const COOMatrix *A)
{
    COOMatrix *out = coo_create(A->rows, A->cols, A->nnz);
    if (!out) return NULL;

    int *idx = (int *)malloc((A->nnz > 0 ? A->nnz : 1) * sizeof(int));
    if (!idx) { coo_destroy(out); return NULL; }
    for (int i = 0; i < A->nnz; i++) idx[i] = i;

    g_coo_sort_data = A;
    qsort(idx, A->nnz, sizeof(int), coo_qsort_cmp);
    g_coo_sort_data = NULL;

    int k = 0;
    for (int i = 0; i < A->nnz; i++) {
        int src = idx[i];
        if (k > 0 && out->row[k-1] == A->row[src] && out->col[k-1] == A->col[src]) {
            out->values[k-1] += A->values[src];
        } else {
            out->row[k] = A->row[src];
            out->col[k] = A->col[src];
            out->values[k] = A->values[src];
            k++;
        }
    }
    out->nnz = k;
    free(idx);
    return out;
}

COOMatrix *csr_to_coo(const CSRMatrix *A)
{
    COOMatrix *out = coo_create(A->rows, A->cols, A->nnz);
    if (!out) return NULL;
    int k = 0;
    for (int i = 0; i < A->rows; i++) {
        for (int j = A->row_ptr[i]; j < A->row_ptr[i+1]; j++) {
            out->row[k] = i;
            out->col[k] = A->col_indices[j];
            out->values[k] = A->values[j];
            k++;
        }
    }
    out->nnz = k;
    return out;
}

CSRMatrix *coo_to_csr(const COOMatrix *A)
{
    COOMatrix *sorted = coo_sort_dedup(A);
    if (!sorted) return NULL;

    CSRMatrix *out = csr_create(sorted->rows, sorted->cols, sorted->nnz);
    if (!out) { coo_destroy(sorted); return NULL; }

    for (int i = 0; i <= sorted->rows; i++) out->row_ptr[i] = 0;

    for (int k = 0; k < sorted->nnz; k++) {
        out->row_ptr[sorted->row[k] + 1]++;
    }
    for (int i = 0; i < sorted->rows; i++) {
        out->row_ptr[i+1] += out->row_ptr[i];
    }

    int *next = (int *)malloc((sorted->rows > 0 ? sorted->rows : 1) * sizeof(int));
    if (!next) { csr_destroy(out); coo_destroy(sorted); return NULL; }
    for (int i = 0; i < sorted->rows; i++) next[i] = out->row_ptr[i];

    for (int k = 0; k < sorted->nnz; k++) {
        int r = sorted->row[k];
        int pos = next[r]++;
        out->col_indices[pos] = sorted->col[k];
        out->values[pos] = sorted->values[k];
    }

    free(next);
    coo_destroy(sorted);
    return out;
}

void csr_spmv(const CSRMatrix *A, const double *x, double *y)
{
    for (int i = 0; i < A->rows; i++) {
        double s = 0.0;
        for (int k = A->row_ptr[i]; k < A->row_ptr[i+1]; k++) {
            s += A->values[k] * x[A->col_indices[k]];
        }
        y[i] = s;
    }
}

static int csr_find_in_row(const CSRMatrix *A, int row, int col)
{
    int lo = A->row_ptr[row];
    int hi = A->row_ptr[row+1] - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (A->col_indices[mid] == col) return mid;
        if (A->col_indices[mid] < col) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

CSRMatrix *csr_transpose(const CSRMatrix *A)
{
    CSRMatrix *T = csr_create(A->cols, A->rows, A->nnz);
    if (!T) return NULL;

    for (int i = 0; i <= A->cols; i++) T->row_ptr[i] = 0;
    for (int k = 0; k < A->nnz; k++) {
        T->row_ptr[A->col_indices[k] + 1]++;
    }
    for (int i = 0; i < A->cols; i++) {
        T->row_ptr[i+1] += T->row_ptr[i];
    }

    int *next = (int *)malloc((A->cols > 0 ? A->cols : 1) * sizeof(int));
    if (!next) { csr_destroy(T); return NULL; }
    for (int i = 0; i < A->cols; i++) next[i] = T->row_ptr[i];

    for (int i = 0; i < A->rows; i++) {
        for (int k = A->row_ptr[i]; k < A->row_ptr[i+1]; k++) {
            int c = A->col_indices[k];
            int pos = next[c]++;
            T->col_indices[pos] = i;
            T->values[pos] = A->values[k];
        }
    }

    free(next);
    return T;
}

int csr_is_symmetric(const CSRMatrix *A, double tol)
{
    if (A->rows != A->cols) return 0;
    for (int i = 0; i < A->rows; i++) {
        for (int k = A->row_ptr[i]; k < A->row_ptr[i+1]; k++) {
            int j = A->col_indices[k];
            int idx = csr_find_in_row(A, j, i);
            if (idx < 0) return 0;
            if (fabs(A->values[k] - A->values[idx]) > tol) return 0;
        }
    }
    return 1;
}

double *csr_diagonal(const CSRMatrix *A)
{
    int n = A->rows < A->cols ? A->rows : A->cols;
    double *diag = vec_create(n);
    if (!diag) return NULL;
    for (int i = 0; i < n; i++) {
        int idx = csr_find_in_row(A, i, i);
        diag[i] = (idx >= 0) ? A->values[idx] : 0.0;
    }
    return diag;
}
