cat > src/precond.c <<'EOF'
#include "precond.h"
#include "vector.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>

static int find_in_row(const CSRMatrix *A, int row, int col)
{
    int lo = A->row_ptr[row];
    int hi = A->row_ptr[row+1] - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (A->col_indices[mid] == col) return mid;
        if (A->col_indices[mid] < col) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

static CSRMatrix *csr_copy(const CSRMatrix *A)
{
    CSRMatrix *B = csr_create(A->rows, A->cols, A->nnz);
    if (!B) return NULL;
    memcpy(B->values, A->values, A->nnz * sizeof(double));
    memcpy(B->col_indices, A->col_indices, A->nnz * sizeof(int));
    memcpy(B->row_ptr, A->row_ptr, (A->rows + 1) * sizeof(int));
    return B;
}

static int ilu0_factorize(CSRMatrix *LU)
{
    int n = LU->rows;
    for (int i = 0; i < n; i++) {
        for (int k = LU->row_ptr[i]; k < LU->row_ptr[i+1]; k++) {
            int c = LU->col_indices[k];
            if (c >= i) break;

            int d = find_in_row(LU, c, c);
            if (d < 0 || fabs(LU->values[d]) < 1e-15) return -1;

            LU->values[k] /= LU->values[d];
            double aik = LU->values[k];

            for (int l = LU->row_ptr[c]; l < LU->row_ptr[c+1]; l++) {
                int j = LU->col_indices[l];
                if (j <= c) continue;
                int idx = find_in_row(LU, i, j);
                if (idx >= 0) LU->values[idx] -= aik * LU->values[l];
            }
        }
    }
    return 0;
}

static int ilu_forward_solve(const CSRMatrix *LU, const double *r, double *y)
{
    for (int i = 0; i < LU->rows; i++) {
        double s = r[i];
        for (int k = LU->row_ptr[i]; k < LU->row_ptr[i+1]; k++) {
            int j = LU->col_indices[k];
            if (j < i) s -= LU->values[k] * y[j];
            else break;
        }
        y[i] = s;
    }
    return 0;
}

static int ilu_backward_solve(const CSRMatrix *LU, const double *y, double *z)
{
    for (int i = LU->rows - 1; i >= 0; i--) {
        double s = y[i];
        int d = -1;
        for (int k = LU->row_ptr[i]; k < LU->row_ptr[i+1]; k++) {
            int j = LU->col_indices[k];
            if (j == i) d = k;
            else if (j > i) s -= LU->values[k] * z[j];
        }
        if (d < 0 || fabs(LU->values[d]) < 1e-15) return -1;
        z[i] = s / LU->values[d];
    }
    return 0;
}

Precond *precond_create(const CSRMatrix *A, const char *name, double omega)
{
    if (!A || !name || A->rows != A->cols) return NULL;

    Precond *P = (Precond *)calloc(1, sizeof(Precond));
    if (!P) return NULL;

    P->n = A->rows;
    P->omega = (omega > 0.0) ? omega : 1.0;

    if (strcmp(name, "none") == 0) {
        P->type = PRECOND_NONE;
    } else if (strcmp(name, "jacobi") == 0) {
        P->type = PRECOND_JACOBI;
        P->diag = csr_diagonal(A);
        if (!P->diag) { precond_destroy(P); return NULL; }
    } else if (strcmp(name, "ilu0") == 0) {
        P->type = PRECOND_ILU0;
        P->lu = csr_copy(A);
        if (!P->lu) { precond_destroy(P); return NULL; }
        if (ilu0_factorize(P->lu) != 0) { precond_destroy(P); return NULL; }
    } else if (strcmp(name, "ssor") == 0) {
        P->type = PRECOND_SSOR;
        P->ssor_A = A;
        P->diag = csr_diagonal(A);
        if (!P->diag) { precond_destroy(P); return NULL; }
    } else {
        precond_destroy(P);
        return NULL;
    }

    return P;
}

void precond_destroy(Precond *P)
{
    if (!P) return;
    free(P->diag);
    csr_destroy(P->lu);
    free(P);
}

int precond_apply(Precond *P, const CSRMatrix *A, const double *r, double *z)
{
    int n = A ? A->rows : (P ? P->n : 0);
    if (!P || P->type == PRECOND_NONE) {
        vec_copy(r, z, n);
        return 0;
    }

    switch (P->type) {
    case PRECOND_JACOBI:
        for (int i = 0; i < n; i++) {
            if (fabs(P->diag[i]) < 1e-15) return -1;
            z[i] = r[i] / P->diag[i];
        }
        return 0;

    case PRECOND_ILU0: {
        double *y = vec_create(n);
        if (!y) return -1;
        if (ilu_forward_solve(P->lu, r, y) != 0) { free(y); return -1; }
        if (ilu_backward_solve(P->lu, y, z) != 0) { free(y); return -1; }
        free(y);
        return 0;
    }

    case PRECOND_SSOR: {
        const CSRMatrix *M = A ? A : P->ssor_A;
        if (!M) return -1;
        vec_zero(z, n);

        for (int i = 0; i < n; i++) {
            double diag = P->diag[i];
            if (fabs(diag) < 1e-15) return -1;
            double sum = 0.0;
            for (int k = M->row_ptr[i]; k < M->row_ptr[i+1]; k++) {
                int j = M->col_indices[k];
                if (j != i) sum += M->values[k] * z[j];
            }
            z[i] = (1.0 - P->omega) * z[i] + (P->omega / diag) * (r[i] - sum);
        }
        for (int i = n - 1; i >= 0; i--) {
            double diag = P->diag[i];
            if (fabs(diag) < 1e-15) return -1;
            double sum = 0.0;
            for (int k = M->row_ptr[i]; k < M->row_ptr[i+1]; k++) {
                int j = M->col_indices[k];
                if (j != i) sum += M->values[k] * z[j];
            }
            z[i] = (1.0 - P->omega) * z[i] + (P->omega / diag) * (r[i] - sum);
        }
        return 0;
    }

    default:
        vec_copy(r, z, n);
        return 0;
    }
}
