cat > src/poisson.c <<'EOF'
#include "poisson.h"
#include "vector.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>

double *poisson_read_source(const char *filename, int nx, int ny)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;

    int rx, ry;
    if (fscanf(fp, "%d %d", &rx, &ry) != 2 || rx != nx || ry != ny) {
        fclose(fp);
        return NULL;
    }

    int n = nx * ny;
    double *f = vec_create(n);
    if (!f) { fclose(fp); return NULL; }

    for (int i = 0; i < n; i++) {
        if (fscanf(fp, "%lf", &f[i]) != 1) {
            free(f);
            fclose(fp);
            return NULL;
        }
    }

    fclose(fp);
    return f;
}

double *poisson_read_boundary(const char *filename, int expected)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;

    double *vals = (double *)malloc(expected * sizeof(double));
    if (!vals) { fclose(fp); return NULL; }

    int count = 0;
    while (count < expected) {
        double v;
        if (fscanf(fp, "%lf", &v) != 1) break;
        vals[count++] = v;
    }

    fclose(fp);
    if (count != expected) { free(vals); return NULL; }
    return vals;
}

static void add_coo(COOMatrix *coo, int *k, int r, int c, double v)
{
    coo->row[*k] = r;
    coo->col[*k] = c;
    coo->values[*k] = v;
    (*k)++;
}

int poisson_assemble(int nx, int ny, double x0, double x1, double y0, double y1,
                    const char *source_file, PoissonBC left, PoissonBC right,
                    PoissonBC bottom, PoissonBC top,
                    CSRMatrix **A_out, double **b_out)
{
    if (!A_out || !b_out) return -1;
    *A_out = NULL;
    *b_out = NULL;

    if (nx < 2 || ny < 2 || x1 <= x0 || y1 <= y0 || !source_file) return -1;

    double hx = (x1 - x0) / (nx - 1);
    double hy = (y1 - y0) / (ny - 1);
    double hx2 = hx * hx;
    double hy2 = hy * hy;

    double *f = poisson_read_source(source_file, nx, ny);
    if (!f) return -1;

    double *left_vals = NULL;
    double *right_vals = NULL;
    double *bottom_vals = NULL;
    double *top_vals = NULL;

    if (left.type == POISSON_NEUMANN) { left_vals = poisson_read_boundary(left.file, ny); if (!left_vals) goto fail; }
    if (right.type == POISSON_NEUMANN) { right_vals = poisson_read_boundary(right.file, ny); if (!right_vals) goto fail; }
    if (bottom.type == POISSON_NEUMANN) { bottom_vals = poisson_read_boundary(bottom.file, nx); if (!bottom_vals) goto fail; }
    if (top.type == POISSON_NEUMANN) { top_vals = poisson_read_boundary(top.file, nx); if (!top_vals) goto fail; }

    if (left.type == POISSON_DIRICHLET) { left_vals = poisson_read_boundary(left.file, ny); if (!left_vals) goto fail; }
    if (right.type == POISSON_DIRICHLET) { right_vals = poisson_read_boundary(right.file, ny); if (!right_vals) goto fail; }
    if (bottom.type == POISSON_DIRICHLET) { bottom_vals = poisson_read_boundary(bottom.file, nx); if (!bottom_vals) goto fail; }
    if (top.type == POISSON_DIRICHLET) { top_vals = poisson_read_boundary(top.file, nx); if (!top_vals) goto fail; }

    int n = nx * ny;
    COOMatrix *coo = coo_create(n, n, 5 * n);
    double *b = vec_create(n);
    if (!coo || !b) { coo_destroy(coo); free(b); goto fail; }

    int k = 0;
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
            int idx = i * ny + j;
            int is_left = (i == 0);
            int is_right = (i == nx - 1);
            int is_bottom = (j == 0);
            int is_top = (j == ny - 1);

            if (is_left && left.type == POISSON_DIRICHLET) {
                add_coo(coo, &k, idx, idx, 1.0);
                b[idx] = left_vals[j];
                continue;
            }
            if (is_right && right.type == POISSON_DIRICHLET) {
                add_coo(coo, &k, idx, idx, 1.0);
                b[idx] = right_vals[j];
                continue;
            }
            if (is_bottom && bottom.type == POISSON_DIRICHLET) {
                add_coo(coo, &k, idx, idx, 1.0);
                b[idx] = bottom_vals[i];
                continue;
            }
            if (is_top && top.type == POISSON_DIRICHLET) {
                add_coo(coo, &k, idx, idx, 1.0);
                b[idx] = top_vals[i];
                continue;
            }

            double diag = 0.0;
            double rhs = f[idx];
            double c_im = 0.0, c_ip = 0.0, c_jm = 0.0, c_jp = 0.0;

            if (is_left && left.type == POISSON_NEUMANN) {
                diag += 2.0 / hx2;
                c_ip = -2.0 / hx2;
                rhs += 2.0 * left_vals[j] / hx;
            } else if (is_right && right.type == POISSON_NEUMANN) {
                diag += 2.0 / hx2;
                c_im = -2.0 / hx2;
                rhs += 2.0 * right_vals[j] / hx;
            } else if (!is_left && !is_right) {
                diag += 2.0 / hx2;
                c_im = -1.0 / hx2;
                c_ip = -1.0 / hx2;
            }

            if (is_bottom && bottom.type == POISSON_NEUMANN) {
                diag += 2.0 / hy2;
                c_jp = -2.0 / hy2;
                rhs += 2.0 * bottom_vals[i] / hy;
            } else if (is_top && top.type == POISSON_NEUMANN) {
                diag += 2.0 / hy2;
                c_jm = -2.0 / hy2;
                rhs += 2.0 * top_vals[i] / hy;
            } else if (!is_bottom && !is_top) {
                diag += 2.0 / hy2;
                c_jm = -1.0 / hy2;
                c_jp = -1.0 / hy2;
            }

            add_coo(coo, &k, idx, idx, diag);
            if (i > 0 && c_im != 0.0) add_coo(coo, &k, idx, (i-1)*ny+j, c_im);
            if (i < nx-1 && c_ip != 0.0) add_coo(coo, &k, idx, (i+1)*ny+j, c_ip);
            if (j > 0 && c_jm != 0.0) add_coo(coo, &k, idx, i*ny+(j-1), c_jm);
            if (j < ny-1 && c_jp != 0.0) add_coo(coo, &k, idx, i*ny+(j+1), c_jp);
            b[idx] = rhs;
        }
    }

    coo->nnz = k;
    CSRMatrix *A = coo_to_csr(coo);
    coo_destroy(coo);
    if (!A) { free(b); goto fail; }

    free(f);
    free(left_vals);
    free(right_vals);
    free(bottom_vals);
    free(top_vals);

    *A_out = A;
    *b_out = b;
    return 0;

fail:
    free(f);
    free(left_vals);
    free(right_vals);
    free(bottom_vals);
    free(top_vals);
    return -1;
}
