static const char *get_opt(int argc, char **argv, const char *name)
{
    for (int i = 0; i < argc - 1; i++) {
        if (strcmp(argv[i], name) == 0) return argv[i+1];
    }
    return NULL;
}

static int write_history_file(const SolveResult *res, const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) return -1;
    for (int i = 0; i < res->history_len; i++) {
        fprintf(fp, "%.15e\n", res->history[i]);
    }
    fclose(fp);
    return 0;
}

static void print_solve_summary(const SolveResult *res)
{
    printf("converged: %s\n", res->converged ? "yes" : "no");
    printf("iterations: %d\n", res->iterations);
    printf("residual: %.6e\n", res->relres);
}

static int cmd_dense_solve(int argc, char **argv)
{
    if (argc < 2) {
        fprintf(stderr, "Error: dense-solve requires <matrix_file> <rhs_file>\n");
        return 1;
    }

    const char *mat_file = argv[0];
    const char *rhs_file = argv[1];
    const char *out_file = (argc >= 3) ? argv[2] : NULL;

    DenseMatrix *A = dm_read_text(mat_file);
    if (!A) {
        fprintf(stderr, "Error: cannot read matrix from '%s'\n", mat_file);
        return 1;
    }

    int n;
    double *b = vec_read_text(rhs_file, &n);
    if (!b) {
        fprintf(stderr, "Error: cannot read RHS from '%s'\n", rhs_file);
        dm_destroy(A);
        return 1;
    }

    if (A->rows != n || A->cols != n) {
        fprintf(stderr, "Error: dimension mismatch A(%d,%d) vs b(%d)\n",
                A->rows, A->cols, n);
        free(b);
        dm_destroy(A);
        return 1;
    }

    double *x = vec_create(n);
    if (!x) {
        fprintf(stderr, "Error: allocation failed\n");
        free(b);
        dm_destroy(A);
        return 1;
    }

    int rc = dm_solve(A, b, x);
    if (rc != 0) {
        fprintf(stderr, "Error: solver failed (singular or ill-conditioned)\n");
        free(x);
        free(b);
        dm_destroy(A);
        return 1;
    }

    if (out_file) {
        vec_write_text(x, n, out_file);
        printf("Solution written to %s\n", out_file);
    } else {
        printf("Solution:\n");
        vec_print(x, n, stdout);
    }

    double *r = vec_create(n);
    dm_matvec(A, x, r);
    vec_axpy(-1.0, b, r, n);
    printf("Residual norm: %.6e\n", vec_norm2(r, n));

    free(r);
    free(x);
    free(b);
    dm_destroy(A);
    return 0;
}

static int parse_bc(const char *s, PoissonBC *bc)
{
    const char *colon = strchr(s, ':');
    if (!colon || colon == s) return -1;

    size_t len = colon - s;
    char type[32];
    if (len >= sizeof(type)) return -1;
    memcpy(type, s, len);
    type[len] = '\0';

    if (strcmp(type, "dirichlet") == 0) bc->type = POISSON_DIRICHLET;
    else if (strcmp(type, "neumann") == 0) bc->type = POISSON_NEUMANN;
    else return -1;

    bc->file = colon + 1;
    return 0;
}

static int run_solver_and_print(const CSRMatrix *A, const double *b,
                                const char *solver, const char *precond,
                                double tol, int maxiter, int restart,
                                double omega, const char *output,
                                const char *history)
{
    Precond *P = precond_create(A, precond, omega);
    if (!P) {
        fprintf(stderr, "Error: cannot create preconditioner '%s'\n", precond);
        return 1;
    }

    SolveResult *res = NULL;
    if (strcmp(solver, "cg") == 0) {
        res = cg_solve(A, b, NULL, tol, maxiter, P);
    } else if (strcmp(solver, "gmres") == 0) {
        res = gmres_solve(A, b, NULL, tol, maxiter, restart, P);
    } else {
        fprintf(stderr, "Error: unknown solver '%s'\n", solver);
        precond_destroy(P);
        return 1;
    }

    if (!res) {
        fprintf(stderr, "Error: solver allocation failed\n");
        precond_destroy(P);
        return 1;
    }

    print_solve_summary(res);

    if (output && vec_write_mm_array(res->x, A->rows, output) != 0) {
        fprintf(stderr, "Error: cannot write output to '%s'\n", output);
    }
    if (history && write_history_file(res, history) != 0) {
        fprintf(stderr, "Error: cannot write history to '%s'\n", history);
    }

    solve_result_destroy(res);
    precond_destroy(P);
    return 0;
}

static int cmd_sparse_solve(int argc, char **argv)
{
    const char *input = get_opt(argc, argv, "--input");
    const char *rhs_file = get_opt(argc, argv, "--rhs");
    const char *solver = get_opt(argc, argv, "--solver");
    const char *precond = get_opt(argc, argv, "--precond");
    const char *tol_s = get_opt(argc, argv, "--tol");
    const char *maxiter_s = get_opt(argc, argv, "--maxiter");
    const char *restart_s = get_opt(argc, argv, "--restart");
    const char *omega_s = get_opt(argc, argv, "--ssor-omega");
    const char *output = get_opt(argc, argv, "--output");
    const char *history = get_opt(argc, argv, "--history");

    if (!input || !rhs_file || !solver || !precond || !tol_s || !maxiter_s) {
        fprintf(stderr, "Error: sparse-solve requires --input, --rhs, --solver, --precond, --tol, --maxiter\n");
        usage("numsim");
        return 1;
    }

    double tol = atof(tol_s);
    int maxiter = atoi(maxiter_s);
    int restart = restart_s ? atoi(restart_s) : 30;
    double omega = omega_s ? atof(omega_s) : 1.0;

    if (tol <= 0.0 || maxiter < 0 || restart <= 0) {
        fprintf(stderr, "Error: invalid solver parameters\n");
        return 1;
    }

    CSRMatrix *A = csr_read_mm(input);
    if (!A) {
        fprintf(stderr, "Error: cannot read sparse matrix from '%s'\n", input);
        return 1;
    }

    int n;
    double *b = vec_read_mm_array(rhs_file, &n);
    if (!b) {
        fprintf(stderr, "Error: cannot read RHS from '%s'\n", rhs_file);
        csr_destroy(A);
        return 1;
    }

    if (A->rows != n || A->cols != n) {
        fprintf(stderr, "Error: dimension mismatch A(%d,%d) vs b(%d)\n",
                A->rows, A->cols, n);
        free(b);
        csr_destroy(A);
        return 1;
    }

    int rc = run_solver_and_print(A, b, solver, precond, tol, maxiter, restart, omega, output, history);

    free(b);
    csr_destroy(A);
    return rc;
}

static int cmd_poisson(int argc, char **argv)
{
    const char *nx_s = get_opt(argc, argv, "--nx");
    const char *ny_s = get_opt(argc, argv, "--ny");
    const char *x0_s = get_opt(argc, argv, "--x0");
    const char *x1_s = get_opt(argc, argv, "--x1");
    const char *y0_s = get_opt(argc, argv, "--y0");
    const char *y1_s = get_opt(argc, argv, "--y1");
    const char *source = get_opt(argc, argv, "--source");
    const char *bc_left_s = get_opt(argc, argv, "--bc-left");
    const char *bc_right_s = get_opt(argc, argv, "--bc-right");
    const char *bc_bottom_s = get_opt(argc, argv, "--bc-bottom");
    const char *bc_top_s = get_opt(argc, argv, "--bc-top");
    const char *solver = get_opt(argc, argv, "--solver");
    const char *precond = get_opt(argc, argv, "--precond");
    const char *tol_s = get_opt(argc, argv, "--tol");
    const char *maxiter_s = get_opt(argc, argv, "--maxiter");
    const char *restart_s = get_opt(argc, argv, "--restart");
    const char *omega_s = get_opt(argc, argv, "--ssor-omega");
    const char *output = get_opt(argc, argv, "--output");
    const char *history = get_opt(argc, argv, "--history");

    if (!nx_s || !ny_s || !x0_s || !x1_s || !y0_s || !y1_s || !source ||
        !bc_left_s || !bc_right_s || !bc_bottom_s || !bc_top_s ||
        !solver || !precond || !tol_s || !maxiter_s) {
        fprintf(stderr, "Error: poisson is missing required arguments\n");
        usage("numsim");
        return 1;
    }

    int nx = atoi(nx_s);
    int ny = atoi(ny_s);
    double x0 = atof(x0_s);
    double x1 = atof(x1_s);
    double y0 = atof(y0_s);
    double y1 = atof(y1_s);
    double tol = atof(tol_s);
    int maxiter = atoi(maxiter_s);
    int restart = restart_s ? atoi(restart_s) : 30;
    double omega = omega_s ? atof(omega_s) : 1.0;

    if (nx < 2 || ny < 2 || x1 <= x0 || y1 <= y0 || tol <= 0.0 || maxiter < 0 || restart <= 0) {
        fprintf(stderr, "Error: invalid poisson parameters\n");
        return 1;
    }

    PoissonBC left, right, bottom, top;
    if (parse_bc(bc_left_s, &left) != 0 || parse_bc(bc_right_s, &right) != 0 ||
        parse_bc(bc_bottom_s, &bottom) != 0 || parse_bc(bc_top_s, &top) != 0) {
        fprintf(stderr, "Error: boundary condition must be <dirichlet|neumann>:<file>\n");
        return 1;
    }

    CSRMatrix *A = NULL;
    double *b = NULL;
    if (poisson_assemble(nx, ny, x0, x1, y0, y1, source, left, right, bottom, top, &A, &b) != 0) {
        fprintf(stderr, "Error: cannot assemble Poisson system\n");
        return 1;
    }

    int rc = run_solver_and_print(A, b, solver, precond, tol, maxiter, restart, omega, output, history);

    free(b);
    csr_destroy(A);
    return rc;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    const char *cmd = argv[1];

    if (strcmp(cmd, "dense-solve") == 0) {
        return cmd_dense_solve(argc - 2, argv + 2);
    } else if (strcmp(cmd, "sparse-solve") == 0) {
        return cmd_sparse_solve(argc - 2, argv + 2);
    } else if (strcmp(cmd, "poisson") == 0) {
        return cmd_poisson(argc - 2, argv + 2);
    } else if (strcmp(cmd, "--help") == 0 || strcmp(cmd, "-h") == 0) {
        usage(argv[0]);
        return 0;
    } else {
        fprintf(stderr, "Error: unknown command '%s'\n", cmd);
        usage(argv[0]);
        return 1;
    }
}
